const city = 'Псков';
const year = 903;

const glued = 'Город ' + city + ', основан в ' + year + ' году';
const template = `Город ${city}, основан в ${year} году`;

document.body.append(glued === template ? 'обе строки одинаковы' : 'строки различаются');

const email = '  Ivan@mail.ru ';

const clean = email.trim().toLowerCase();  // 'ivan@mail.ru'
const at = clean.indexOf('@');             // 4
const domain = clean.slice(at + 1);        // 'mail.ru'
const isKnown = domain.includes('mail');   // true

document.body.append(clean + ' | ' + domain + ' | ' + isKnown);

const tags = 'js,html,css';
const list = tags.split(',');   // ['js', 'html', 'css']
const path = list.join(' -> '); // 'js -> html -> css'

const size = parseInt('42px', 10); // 42 — parseInt читает число до первой буквы
const binary = parseInt('11', 2);  // 3 — а здесь основание 2

document.body.append(path + ' | ' + size + ' | ' + binary);

